<?php
require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $db=getDB(); if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf_token']??null)){ $id=(int)post('withdrawal_id'); $action=(string)post('action'); $s=$db->prepare('SELECT * FROM withdrawals WHERE id=? AND status="pending"'); $s->execute([$id]); $w=$s->fetch(); if($w){if($action==='approve'){$db->prepare('UPDATE withdrawals SET status="approved",reviewed_at=NOW() WHERE id=?')->execute([$id]);$db->prepare('UPDATE transactions SET status="completed" WHERE reference_id=? AND type="withdrawal"')->execute([$id]);flash('success','Withdrawal approved.');}elseif($action==='reject'){$db->beginTransaction();$db->prepare('UPDATE withdrawals SET status="rejected",reviewed_at=NOW() WHERE id=?')->execute([$id]);$db->prepare('UPDATE wallets SET balance=balance+?,total_withdrawn=GREATEST(total_withdrawn-?,0),updated_at=NOW() WHERE user_id=?')->execute([$w['amount'],$w['amount'],$w['user_id']]);$db->prepare('UPDATE transactions SET status="failed" WHERE reference_id=? AND type="withdrawal"')->execute([$id]);$db->commit();flash('success','Withdrawal rejected and balance refunded.');}} redirect(appUrl('admin/withdrawals.php')); } $rows=$db->query('SELECT w.*,u.username FROM withdrawals w JOIN users u ON u.id=w.user_id ORDER BY w.created_at DESC')->fetchAll(); $pageTitle='Withdrawals';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">PAYOUT QUEUE</span><h1>Withdrawals</h1></div><?php foreach(consumeFlashes() as $f): ?><div class="alert <?= e($f['type']) ?>"><?= e($f['message']) ?></div><?php endforeach; ?><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Amount</th><th>Method</th><th>Account</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $w): ?><tr><td><?= e($w['username']) ?></td><td><?= formatCurrency($w['amount']) ?></td><td><?= e($w['payment_method']) ?></td><td><?= e($w['account_details']) ?></td><td><span class="badge <?= e($w['status']) ?>"><?= e(ucfirst($w['status'])) ?></span></td><td><?php if($w['status']==='pending'): ?><form method="post" class="inline-form"><?= csrfField() ?><input type="hidden" name="withdrawal_id" value="<?= e($w['id']) ?>"><button name="action" value="approve" class="btn small primary">Approve</button><button name="action" value="reject" class="btn small danger">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
